definition.script:
node {
    stage('Use DisCo audit folder secret') {
        withCredentials([
            string(credentialsId: 'disco-team-alpha-secret', variable: 'DISCO_TEAM_ALPHA_SECRET'),
            string(credentialsId: 'disco-audit-secret', variable: 'DISCO_AUDIT_SECRET')
        ]) {
            sh '''#!/bin/bash
            set -euo pipefail
            test -n "$DISCO_TEAM_ALPHA_SECRET"
            test -n "$DISCO_AUDIT_SECRET"
            echo "DisCo audit folder credential bindings succeeded"
            '''
        }
    }
}
